import sys

def main():
    data = sys.stdin.read().strip().splitlines()
    vals = {}
    for line in data:
        k, v = line.split("=")
        vals[k.strip()] = int(v.strip())
    n, bad = vals["n"], vals["bad"]
    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if mid >= bad:
            hi = mid
        else:
            lo = mid + 1
    print(lo)

