import sys, ast, json

def main():
    data = sys.stdin.read().strip()
    strs = ast.literal_eval(data.split("=", 1)[1].strip())
    if not strs:
        print(json.dumps(""))
        return
    pref = strs[0]
    for s in strs[1:]:
        while not s.startswith(pref):
            pref = pref[:-1]
            if not pref:
                break
    print(json.dumps(pref))

main()
